with prev_events as (select *, lag(paid_at) over (partition by order_id order by paid_at, id) as prev_paid_at from payments), gaps as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval '7' day then 1 else 0 end as session_start_flag from prev_events) select *, sum(session_start_flag) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as burst_id from gaps
